const { mensaje } = $input.first().json;
const apiKey = $env.ANTHROPIC_API_KEY;

const systemPrompt = `Sos un agente de atención al cliente amable y profesional. Tu objetivo es ayudar a los clientes a resolver sus dudas y problemas de forma clara y empática.

Reglas:
- Respondé siempre en el mismo idioma que el cliente.
- Sé conciso: máximo 3 oraciones por respuesta (es WhatsApp, no un email).
- Si no sabés la respuesta, decí honestamente que vas a derivar la consulta a un humano.
- Nunca inventes información sobre precios, políticas o productos.
- Usá un tono cálido pero profesional, sin ser demasiado formal.`;

const response = await fetch('https://api.anthropic.com/v1/messages', {
  method: 'POST',
  headers: {
    'x-api-key': apiKey,
    'anthropic-version': '2023-06-01',
    'content-type': 'application/json'
  },
  body: JSON.stringify({
    model: 'claude-sonnet-4-6',
    max_tokens: 1024,
    system: systemPrompt,
    messages: [{ role: 'user', content: mensaje }]
  })
});

const data = await response.json();
const respuesta = data.content[0].text;

return [{
  json: {
    respuesta,
    ...$input.first().json
  }
}];

const { respuesta, de, para } = $input.first().json;
const accountSid = $env.TWILIO_ACCOUNT_SID;
const authToken = $env.TWILIO_AUTH_TOKEN;

const credentials = Buffer.from(`${accountSid}:${authToken}`).toString('base64');

const body = new URLSearchParams({
  From: para,
  To: de,
  Body: respuesta
}).toString();

const response = await fetch(
  `https://api.twilio.com/2010-04-01/Accounts/${accountSid}/Messages.json`,
  {
    method: 'POST',
    headers: {
      'Authorization': `Basic ${credentials}`,
      'Content-Type': 'application/x-www-form-urlencoded'
    },
    body
  }
);

const data = await response.json();
return [{ json: { sid: data.sid, status: data.status } }];
